// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint blockTime, uint blockNum, uint value) public {
        vm.assume(sender != address(0) && value == 10 ether);
        vm.assume(blockTime < type(uint).max);
        vm.deal(sender, 10 ether);
        vm.warp(blockTime);
        vm.roll(blockNum);
        uint oldPastBlockTime = c.pastBlockTime();
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        if (success) {
            uint newPastBlockTime = c.pastBlockTime();
            assertTrue(newPastBlockTime > blockTime, "pastBlockTime should be > block.timestamp");
        } else {
            assertTrue(c.pastBlockTime() == oldPastBlockTime, "on revert, pastBlockTime unchanged");
        }
    }
}

